const CRM_BASE_URL = 'https://rrespocrm-rsg-u69864.vm.elestio.app';

return $input.all().map((item) => ({
  json: {
    ...item.json,
    crmBaseUrlFromCred: CRM_BASE_URL,
  },
  pairedItem: item.pairedItem,
}));

const SLACK_DM_MAP = {
  'Lamar Coates':    'D09MBKK5YCU',
  'Gretchen Coates': 'D09NPN3MHB3',
  'Terrance':        'D0AUS4NPG3T',
};
const FALLBACK_CHANNEL = 'C09LSKBF6KZ';

const task = $input.first().json;
const assignedName = task.assignedUserName || '';
const slackChannelId = SLACK_DM_MAP[assignedName] || FALLBACK_CHANNEL;
const mention = `*${assignedName || 'Unassigned'}*`;

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: '🔴 NEW TASK ASSIGNED', emoji: true }
  },
  {
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `*Task:*\n${task.taskName || '(no name)'}` },
      { type: 'mrkdwn', text: `*👤 Assigned To:*\n${mention}` },
      { type: 'mrkdwn', text: `*📅 Due:*\n${task.dateEnd || '—'}` },
      { type: 'mrkdwn', text: `*🏢 Account:*\n${task.accountName || '—'}` }
    ]
  },
  task.taskUrl ? {
    type: 'section',
    text: { type: 'mrkdwn', text: `🔗 <${task.taskUrl}|Open in CRM>` }
  } : null,
  {
    type: 'actions',
    elements: [
      {
        type: 'button',
        text: { type: 'plain_text', text: '📥 Archive', emoji: true },
        style: 'danger',
        action_id: 'archive_task_message',
        value: task.taskId || 'unknown',
        confirm: {
          title: { type: 'plain_text', text: 'Archive this task?' },
          text: { type: 'mrkdwn', text: 'This will remove the message from Slack.' },
          confirm: { type: 'plain_text', text: 'Archive' },
          deny: { type: 'plain_text', text: 'Cancel' }
        }
      }
    ]
  }
].filter(Boolean);

return [{ json: { ...task, mention, slackChannelId, blocks } }];
